export function browseSetupFolder(): void {
  currentBrowseTarget = 'setup_workspace';
  const pathInput = document.getElementById('setupWorkspacePath') as HTMLInputElement | null;
  const startPath = pathInput?.value.trim() || getFeatureRegistry().browseHomeDir || '';
  currentBrowsePath = startPath;
  const manualPathInput = document.getElementById('manualPathInput') as HTMLInputElement | null;
  if (manualPathInput) manualPathInput.value = startPath;
  if (startPath) {
    if (typeof getFeatureRegistry().loadFolderList === 'function') getFeatureRegistry().loadFolderList(startPath);
  } else {
    if (typeof getFeatureRegistry().loadFolderDrives === 'function') getFeatureRegistry().loadFolderDrives();
  }
  const folderModal = document.getElementById('folderModal');
  if (folderModal) folderModal.classList.add('active');
}

export function browseFolder(target: string): void {
  currentBrowseTarget = target;
  getFeatureRegistry().currentBrowseTarget = target;
  const field = document.getElementById(`setting${target.split('_').map(part => part ? part[0].toUpperCase() + part.slice(1) : '').join('')}`) as HTMLInputElement | null;
  const explicitMap: Record<string, string> = {
    workspace_dir: 'settingWorkspaceDir',
    documents_dir: 'settingDocumentsDir',
    images_dir: 'settingImagesDir',
    chats_dir: 'settingChatsDir',
  };
  const input = document.getElementById(explicitMap[target] || '') as HTMLInputElement | null;
  const startPath = (input || field)?.value.trim() || getFeatureRegistry().browseHomeDir || '';
  currentBrowsePath = startPath;
  getFeatureRegistry().currentBrowsePath = startPath;
  const manualPathInput = document.getElementById('manualPathInput') as HTMLInputElement | null;
  if (manualPathInput) manualPathInput.value = startPath;
  if (startPath && typeof getFeatureRegistry().loadFolderList === 'function') {
    getFeatureRegistry().loadFolderList(startPath);
  } else if (typeof getFeatureRegistry().loadFolderDrives === 'function') {
    getFeatureRegistry().loadFolderDrives();
  }
  document.getElementById('folderModal')?.classList.add('active');
}

export function closeFolderModal(): void {
  document.getElementById('folderModal')?.classList.remove('active');
  currentBrowseTarget = null;
  getFeatureRegistry().currentBrowseTarget = null;
}

export async function confirmFolderSelect(): Promise<void> {
  const path = ((document.getElementById('manualPathInput') as HTMLInputElement | null)?.value || '').trim();
  const target = currentBrowseTarget || getFeatureRegistry().currentBrowseTarget;
  if (!path || !target) return;
  if (target === 'setup_workspace') {
    const input = document.getElementById('setupWorkspacePath') as HTMLInputElement | null;
    if (input) input.value = path;
    closeFolderModal();
    return;
  }
  await updateSetting('storage', target, path);
  const inputMap: Record<string, string> = {
    workspace_dir: 'settingWorkspaceDir',
    documents_dir: 'settingDocumentsDir',
    images_dir: 'settingImagesDir',
    chats_dir: 'settingChatsDir',
  };
  const input = document.getElementById(inputMap[target] || '') as HTMLInputElement | null;
  if (input) input.value = path;
  closeFolderModal();
}

// ── Status / Latency ──
export function getLatencyClass(latencyMs: number | null): string {
  if (latencyMs == null) return '';
  if (latencyMs < 500) return 'good';
  if (latencyMs < 1500) return 'ok';
  return 'slow';
}

export function formatLatency(providerData: any): string {
  if (!providerData) return '--';
  if (providerData.error === 'checking') return '检查中';
  if (providerData.reachable && providerData.latency_ms != null) return `${providerData.latency_ms}ms`;
  if (providerData.error === 'runtime_outdated') {
    return providerData.required_version ? `需 Ollama ${providerData.required_version}` : '需升级 Ollama';
  }
  const errors: Record<string, string> = {
    key_missing: 'Key 未配置', key_invalid: 'Key 不可用', model_missing: '未选模型',
    model_not_found: '模型不存在', model_load_failed: '模型损坏', rate_limited: '限流中', timeout: '超时',
    service_unavailable: '未启动', network_error: '网络异常', checking: '检查中',
  };
  return errors[String(providerData.error || '')] || '不可用';
}

export function updateLatencyProvider(provider: string, providerData: any): void {
  const id = provider === 'local' ? 'Local' : 'Deepseek';
  const row = document.getElementById(`latency${id}`);
  const value = document.getElementById(`latency${id}Val`);
  const bar = document.getElementById(`latency${id}Bar`);
  const label = document.getElementById(`latency${id}Name`);
  const latencyMs = providerData && providerData.reachable ? providerData.latency_ms : null;
  const latencyClass = getLatencyClass(latencyMs);
  if (value) value.textContent = formatLatency(providerData);
  if (label && providerData?.model_id) label.textContent = provider === 'local' ? `本地 · ${providerData.model_id}` : `DeepSeek · ${providerData.model_id}`;
  if (bar) { bar.className = `latency-bar-fill ${latencyMs == null ? 'failed' : latencyClass}`.trim(); bar.style.width = latencyMs == null ? '100%' : `${Math.max(8, Math.min(100, latencyMs / 20))}%`; }
  if (row) { row.classList.toggle('offline', !(providerData && providerData.reachable)); }
}

export function updateLatencyDetail(results: any): void {
  updateLatencyProvider('deepseek', results && results.deepseek);
  updateLatencyProvider('local', results && results.local);
}

export function toggleLatencyDetail(event?: Event): void {
  if (event) event.stopPropagation();
  const detail = document.getElementById('latencyDetail');
  if (!detail) return;
  const willOpen = !detail.classList.contains('open');
  if (willOpen) {
    updateLatencyDetail(getFeatureRegistry()._lastModelLatency || { deepseek: { reachable: false, error: 'checking' }, local: { reachable: false, error: 'checking' } });
    checkStatus(true);
  }
  // The status detail belongs to the task sidebar.  Moving it into the file
  // browser made a global component participate in the workspace column's
  // flex layout, which caused both panels to overlap in narrow windows.
  // Keep its DOM owner stable; the activity-rail CSS positions it as a popover.
  if (detail) detail.style.display = willOpen ? 'block' : 'none';
  detail.classList.toggle('open', willOpen);
  const arrow = document.querySelector('.status-expand-arrow'); if (arrow) arrow.classList.toggle('open', willOpen);
  const indicator = document.getElementById('statusIndicator'); if (indicator) indicator.setAttribute('aria-expanded', willOpen ? 'true' : 'false');
}

export async function checkStatus(probeModels: boolean = false): Promise<void> {
  const dot = document.querySelector('.status-dot');
  const text = document.querySelector('.status-text');

  const noticeBar = document.getElementById('wechat-notice-bar');
  try {
    const endpoint = probeModels ? '/api/ping/models' : '/api/capabilities';
    const timeout = probeModels ? 25000 : 3000;
    const cResp = await fetch(endpoint, { signal: AbortSignal.timeout(timeout), cache: 'no-store' });
    if (cResp.ok) {
      const models = await cResp.json();
      if (probeModels) {
        getFeatureRegistry()._lastModelLatency = models;
        updateLatencyDetail(models);
      }
      const active = probeModels ? models?.active : models?.capabilities?.active_model;
      const activeMode = probeModels ? active?.mode : active?.metadata?.mode;
      const isReady = probeModels ? active?.reachable : ['available', 'checking'].includes(active?.status);
      if (isReady) {
        const provider = activeMode === 'local' ? '本地' : 'DeepSeek';
        const latency = activeMode === 'local' ? models.local?.latency_ms : models.deepseek?.latency_ms;
        if (dot) { dot.classList.add('online'); dot.classList.remove('offline'); }
        if (text) text.textContent = probeModels
          ? `${provider} ${latency}ms`
          : (active?.status === 'checking' ? `${provider} 待检测` : `${provider} 已配置`);
        if (noticeBar) noticeBar.style.display = 'none';
      } else {
        const provider = activeMode === 'local' ? '本地' : 'DeepSeek';
        const capabilityText: Record<string, string> = {
          misconfigured: `${provider} 待配置`,
          unavailable: `${provider} 服务未启动`,
          incompatible: `${provider} 运行时需升级`,
        };
        if (dot) { dot.classList.add('offline'); dot.classList.remove('online'); }
        if (text) text.textContent = probeModels ? `${provider} 不可用` : (capabilityText[active?.status] || `${provider} 不可用`);
        if (noticeBar) noticeBar.style.display = 'block';
      }
    } else {
      if (dot) { dot.classList.add('offline'); dot.classList.remove('online'); }
      if (text) text.textContent = '模型检查失败';
      if (noticeBar) noticeBar.style.display = 'block';
    }
  } catch (_) {
    updateLatencyDetail(getFeatureRegistry()._lastModelLatency || {});
    if (dot) { dot.classList.add('offline'); dot.classList.remove('online'); }
    if (text) text.textContent = '模型检查失败';
    if (noticeBar) noticeBar.style.display = 'block';
  }

  try {
    const mResp = await fetch('/api/ops/metrics', { signal: AbortSignal.timeout(3000) });
    if (mResp.ok) {
      const m = await mResp.json();
      const trigEnabled = (m.triggers && m.triggers.enabled) || 0;
      const pill = document.getElementById('jobsRunningPill'); if (pill) pill.style.display = 'none';
      const badge = document.getElementById('opsStatusBadge');
      if (badge && trigEnabled > 0) { badge.textContent = `${trigEnabled} 触发器活跃`; badge.style.display = 'block'; }
      else if (badge) badge.style.display = 'none';
    }
  } catch (_) { /* ignore */ }
}

// ── Batch Jobs Panel ──
const batchJobsState = { timer: null as ReturnType<typeof setInterval> | null };

export function openBatchJobsPanel(): void {
  const modal = document.getElementById('batchPanelModal');
  if (!modal) return;
  modal.classList.add('active');
  modal.setAttribute('aria-hidden', 'false');
  requestAnimationFrame(() => {
    (modal.querySelector('.ui-close-button') as HTMLElement | null)?.focus();
  });
  refreshBatchJobs();
  if (batchJobsState.timer) clearInterval(batchJobsState.timer);
  batchJobsState.timer = setInterval(refreshBatchJobs, 2000);
}

export function closeBatchJobsPanel(): void {
  const modal = document.getElementById('batchPanelModal');
  if (modal) {
    modal.classList.remove('active');
    modal.setAttribute('aria-hidden', 'true');
  }
  if (batchJobsState.timer) { clearInterval(batchJobsState.timer); batchJobsState.timer = null; }
}

export async function refreshBatchJobs(): Promise<void> {
  try {
    const response = await fetch('/api/batch/jobs');
    const data = await response.json();
    if (!data.success) return;
    const listEl = document.getElementById('batchJobsList');
    const jobs = data.jobs || [];
    if (!listEl) return;
    if (jobs.length === 0) { listEl.innerHTML = '<div class="batch-empty">暂无任务</div>'; return; }
    listEl.innerHTML = jobs.map((job: any) => {
      const total = job.total_items || 0;
      const processed = job.processed_items || 0;
      const percent = total > 0 ? Math.round((processed / total) * 100) : 0;
      const outputDir = job.output_dir || '';
      const encodedOutput = encodeURIComponent(outputDir);
      const status = job.status || 'unknown';
      return `<div class="batch-job-card"><div class="batch-job-title">${escHtml(job.name || job.job_id)}</div><div class="batch-job-meta"><span>状态: ${escHtml(status)}</span><span>${processed}/${total}</span></div><div class="batch-job-progress"><div class="batch-job-progress-fill" style="width:${percent}%"></div></div><div class="batch-job-meta batch-job-output"><span>${escHtml(outputDir)}</span><button class="ui-ghost-button ui-ghost-button--compact" data-koto-action="copy-output-path" data-path="${encodedOutput}">复制路径</button></div></div>`;
    }).join('');
  } catch (_error) { /* ignore */ }
}

export async function resetSettings(): Promise<void> {
  if (!confirm('确定要重置所有设置为默认值吗？')) return;
  try {
    const response = await csrfFetch('/api/settings/reset', { method: 'POST' });
    const data = await response.json();
    if (!response.ok || data.success === false) throw new Error(data.error || '重置失败');
    await loadSettings();
    if (typeof getFeatureRegistry().showNotification === 'function') {
      getFeatureRegistry().showNotification('设置已恢复默认', 'success', 1800);
    }
  } catch (error: any) {
    if (typeof getFeatureRegistry().showNotification === 'function') {
      getFeatureRegistry().showNotification('重置失败: ' + (error.message || error), 'error');
    }
  }
}

export function openPath(path: string): void { if (path) copyPathToClipboard(path, '输出路径'); }

function copyPathToClipboard(path: string, label: string = '路径'): void {
  navigator.clipboard.writeText(path).then(() => {
    if (typeof getFeatureRegistry().showNotification === 'function') getFeatureRegistry().showNotification(`已复制${label}`, 'success', 1500);
  }).catch(() => { prompt(`复制${label}：`, path); });
}

function escHtml(str: string): string {
  return String(str || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

